function persistDraft(active){if(active.preview)return true;const previous=state().interactiveV1;const journal=Interactive.journal(state());const draft={version:1,id:active.id,nodeId:active.node.id,plan:active.plan,questions:active.questions,results:active.results,index:active.index,phase:active.phase,guided:!!active.guided,pending:active.pending||null,challengeDay:active.challengeDay||null};if(!Interactive.validateDraft(draft))throw Error('Invalid draft');state().interactiveV1={...journal,sessions:{...journal.sessions,[active.id]:structuredClone(draft)},activeId:active.id};try{save();return true;}catch(error){if(previous===undefined)delete state().interactiveV1;else state().interactiveV1=previous;throw error;}}
function resumeDraft(id){const journal=Interactive.journal(state());const candidates=Object.values(journal.sessions).filter(d=>Interactive.validateDraft(d)&&(!id||d.nodeId===id)&&!(state().runs||[]).some(r=>r.id===d.id));const draft=candidates.find(d=>d.id===journal.activeId)||candidates.at(-1);if(!draft)return null;const node=R.nodes.find(n=>n.id===draft.nodeId);if(!id&&skippedOptional.has(node?.id))return null;if(!node||state().overrides?.[node.id]==='lock'||state().homework&&state().homework!==node.id||!R.available(learningState(),node)&&state().homework!==node.id)return null;if(state().difficulty&&state().difficulty!=='auto'&&state().difficulty!==draft.plan.difficulty)return null;if(state().sessionMode&&state().sessionMode!=='auto'&&state().sessionMode!==draft.plan.mode)return null;if(safePool(draft.questions,node).length!==draft.questions.length||draft.questions.some(q=>!activityPolicy(node,draft.plan.mode==='assessment'?'assessment':'practice',q)))return null;return {...structuredClone(draft),node,preview:false};}

