function save(){if(broken)throw Error('تعذر قراءة السجل الأصلي؛ لم يتم استبداله.');if(localStorage.getItem(KEY)!==lastSavedRaw)throw Error('تغير السجل في نافذة أخرى؛ أعد فتح الرحلة دون استبداله.');const next=JSON.stringify(store);localStorage.setItem(KEY,next);lastSavedRaw=next;}
